<h2>Calculate network bandwidth requirement</h2><p class="lead">Estimate total throughput requirement from concurrent users and per-user demand, with overhead and file-transfer context.</p><div class="notice">This calculator uses decimal networking units: 1 Gbps = 1,000 Mbps and 1 byte = 8 bits. Real throughput is lower than link rate because protocols and contention consume capacity.</div><div class="form-grid"><div class="field"><label for="users">Concurrent users / streams</label><input id="users" type="number" value="50" min="0" step="any"></div><div class="field"><label for="per">Average Mbps per user / stream</label><input id="per" type="number" value="3" min="0" step="any"></div><div class="field"><label for="over">Protocol / growth headroom (%)</label><input id="over" type="number" value="25" min="0" step="any"></div><div class="field"><label for="file">Optional file size (GB)</label><input id="file" type="number" value="5" min="0" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Raw aggregate demand</span><strong id="raw">—</strong></div><div class="metric"><span>Bandwidth with headroom</span><strong id="recommended">—</strong></div><div class="metric"><span>Equivalent Gbps</span><strong id="gbps">—</strong></div><div class="metric"><span>Entered file transfer time at recommended rate</span><strong id="transfer">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('raw').textContent='—';$('recommended').textContent='—';$('gbps').textContent='—';$('transfer').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const u=num('users'),p=num('per'),o=num('over')/100,f=num('file');if(!(u>=0&&p>=0&&o>=0&&f>=0))throw 0;const raw=u*p,bw=raw*(1+o),sec=bw>0?f*8*1000/bw:Infinity;$('raw').textContent=fmt(raw,2)+' Mbps';$('recommended').textContent=fmt(bw,2)+' Mbps';$('gbps').textContent=fmt(bw/1000,4)+' Gbps';$('transfer').textContent=Number.isFinite(sec)?fmt(sec/60,2)+' min':'Unavailable';$('note').textContent='Bandwidth is a rate, not a guarantee of application performance. Latency, packet loss, Wi-Fi airtime, traffic bursts and provider contention also matter.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
